contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint256 amount, address logAddr) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        require(address(this).balance >= amount);

        c.SetLogFile(logAddr); if (__ESBMC_reverted()) return;

        uint256 callerBefore = c.balances(address(this)); if (__ESBMC_reverted()) return;
        uint256 cBalanceBefore = address(c).balance;

        bool reverted;
        c.Deposit{value: amount}(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint256 callerAfter = c.balances(address(this)); if (__ESBMC_reverted()) return;
        uint256 cBalanceAfter = address(c).balance;

        assert((!reverted && callerAfter == callerBefore + amount && cBalanceAfter == cBalanceBefore + amount) || (reverted && callerAfter == callerBefore && cBalanceAfter == cBalanceBefore));
    }

    receive() external payable {}
}

