import {Test} from "forge-std/Test.sol";
import {PRIVATE_ETH_CELL} from "../src/PRIVATE_ETH_CELL.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    PRIVATE_ETH_CELL c;

    function setUp() public {
        c = new PRIVATE_ETH_CELL();
    }

    function _run(uint256 amount, address logAddr) internal {
        amount = bound(amount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= amount);
        try c.SetLogFile(logAddr) {} catch { return; }
        uint256 callerBefore;
        try c.balances(address(this)) returns (uint256 __r) { callerBefore = __r; } catch { return; }
        uint256 cBalanceBefore = address(c).balance;
        bool reverted;
        try c.Deposit{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint256 callerAfter;
        try c.balances(address(this)) returns (uint256 __r) { callerAfter = __r; } catch { return; }
        uint256 cBalanceAfter = address(c).balance;
        assertTrue((!reverted && callerAfter == callerBefore + amount && cBalanceAfter == cBalanceBefore + amount) || (reverted && callerAfter == callerBefore && cBalanceAfter == cBalanceBefore));
